import { redirect } from "next/navigation";

export default function Home() {
  redirect("/sessions/new");
}

import { exec } from "node:child_process";
import { promises as fs } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";

import { stepCountIs, tool, ToolLoopAgent } from "ai";
import type { InferAgentUIMessage } from "ai";
import { z } from "zod";

import { getModel } from "@/lib/llm";

const execAsync = promisify(exec);

const MAX_READ_BYTES = 64 * 1024;
const MAX_GREP_MATCHES = 100;
const SHELL_TIMEOUT_MS = 30_000;

const projectRoot = (): string => process.cwd();

const resolveWithinProject = (target: string): string => {
  const root = projectRoot();
  const resolved = path.resolve(root, target);
  if (resolved !== root && !resolved.startsWith(`${root}${path.sep}`)) {
    throw new Error(
      `Path ${target} escapes the project directory and is not allowed.`
    );
  }
  return resolved;
};

const readFileTool = tool({
  description:
    "Read the contents of a file in the project. Paths are relative to the project root. Output is truncated if the file exceeds 64 KiB.",
  execute: async ({ path: target }) => {
    const absolute = resolveWithinProject(target);
    const buffer = await fs.readFile(absolute);
    if (buffer.byteLength > MAX_READ_BYTES) {
      const truncated = buffer.subarray(0, MAX_READ_BYTES).toString("utf-8");
      return {
        bytes: buffer.byteLength,
        content: truncated,
        path: target,
        truncated: true,
      };
    }
    return {
      bytes: buffer.byteLength,
      content: buffer.toString("utf-8"),
      path: target,
      truncated: false,
    };
  },
  inputSchema: z.object({
    path: z.string().describe("Path to the file, relative to the project root"),
  }),
});

const writeFileTool = tool({
  description:
    "Write text content to a file in the project. Creates parent directories as needed. Overwrites any existing file at the path.",
  execute: async ({ path: target, content }) => {
    const absolute = resolveWithinProject(target);
    await fs.mkdir(path.dirname(absolute), { recursive: true });
    await fs.writeFile(absolute, content, "utf-8");
    return { bytesWritten: Buffer.byteLength(content, "utf-8"), path: target };
  },
  inputSchema: z.object({
    content: z.string().describe("UTF-8 text content to write"),
    path: z.string().describe("Path to the file, relative to the project root"),
  }),
});

const editFileTool = tool({
  description:
    "Replace an exact substring inside an existing file. The substring must occur exactly once. Use this for surgical edits instead of rewriting the entire file.",
  execute: async ({ path: target, oldText, newText }) => {
    const absolute = resolveWithinProject(target);
    const original = await fs.readFile(absolute, "utf-8");
    const firstIndex = original.indexOf(oldText);
    if (firstIndex === -1) {
      throw new Error(`oldText was not found in ${target}.`);
    }
    if (original.includes(oldText, firstIndex + 1)) {
      throw new Error(
        `oldText occurs more than once in ${target}; provide more context to make it unique.`
      );
    }
    const updated =
      original.slice(0, firstIndex) +
      newText +
      original.slice(firstIndex + oldText.length);
    await fs.writeFile(absolute, updated, "utf-8");
    return { path: target, replaced: 1 };
  },
  inputSchema: z.object({
    newText: z.string().describe("Replacement text"),
    oldText: z.string().describe("Substring that must occur exactly once"),
    path: z.string().describe("Path to the file, relative to the project root"),
  }),
});

const grepTool = tool({
  description:
    "Search for a fixed-string pattern in the project using git grep. Returns up to 100 matches with file path and line number.",
  execute: async ({ pattern, path: target }) => {
    const args = ["grep", "-nF", "--", pattern];
    if (target) {
      args.push(resolveWithinProject(target));
    }
    const command = `git ${args.map((arg) => JSON.stringify(arg)).join(" ")}`;
    try {
      const { stdout } = await execAsync(command, {
        cwd: projectRoot(),
        maxBuffer: 4 * 1024 * 1024,
      });
      const lines = stdout.split("\n").filter((line) => line.length > 0);
      const matches = lines.slice(0, MAX_GREP_MATCHES).map((line) => {
        const firstColon = line.indexOf(":");
        const secondColon = line.indexOf(":", firstColon + 1);
        return {
          file: line.slice(0, firstColon),
          line: Number.parseInt(line.slice(firstColon + 1, secondColon), 10),
          text: line.slice(secondColon + 1),
        };
      });
      return {
        matches,
        pattern,
        totalMatches: lines.length,
        truncated: lines.length > MAX_GREP_MATCHES,
      };
    } catch (error) {
      const err = error as { code?: number; stderr?: string };
      if (err.code === 1) {
        return { matches: [], pattern, totalMatches: 0, truncated: false };
      }
      throw new Error(err.stderr?.trim() || (error as Error).message, {
        cause: error,
      });
    }
  },
  inputSchema: z.object({
    path: z
      .string()
      .optional()
      .describe(
        "Optional path or pathspec to limit the search, relative to the project root"
      ),
    pattern: z.string().describe("Fixed-string pattern to search for"),
  }),
});

const shellTool = tool({
  description:
    "Run a shell command in the project root. Use sparingly; prefer the dedicated file tools for reading and editing. Times out after 30 seconds.",
  execute: async ({ command }) => {
    try {
      const { stdout, stderr } = await execAsync(command, {
        cwd: projectRoot(),
        maxBuffer: 4 * 1024 * 1024,
        timeout: SHELL_TIMEOUT_MS,
      });
      return { command, exitCode: 0, stderr, stdout };
    } catch (error) {
      const err = error as {
        code?: number;
        stdout?: string;
        stderr?: string;
        killed?: boolean;
        signal?: string;
        message: string;
      };
      return {
        command,
        exitCode: typeof err.code === "number" ? err.code : 1,
        killed: err.killed === true,
        signal: err.signal,
        stderr: err.stderr ?? err.message,
        stdout: err.stdout ?? "",
      };
    }
  },
  inputSchema: z.object({
    command: z.string().describe("Shell command to execute"),
  }),
});

export const tools = {
  editFile: editFileTool,
  grep: grepTool,
  readFile: readFileTool,
  shell: shellTool,
  writeFile: writeFileTool,
} as const;

export const systemPrompt = `You are Codify, an autonomous coding agent working inside the user's project directory.

You have tools to read files, write files, edit files with surgical replacements, grep the codebase, and run shell commands. Use them to understand the project before making changes, and prefer the dedicated file tools over the shell tool when possible. Keep responses concise and explain what you did after the tool calls have finished.`;

const buildAgent = () =>
  new ToolLoopAgent({
    instructions: systemPrompt,
    model: getModel(),
    stopWhen: stepCountIs(20),
    tools,
  });

let cachedAgent: ReturnType<typeof buildAgent> | null = null;

export const getAgent = (): ReturnType<typeof buildAgent> => {
  if (!cachedAgent) {
    cachedAgent = buildAgent();
  }
  return cachedAgent;
};

export type CodifyUIMessage = InferAgentUIMessage<
  ReturnType<typeof buildAgent>
>;

import { promises as fs } from "node:fs";
import path from "node:path";

import type { UIMessage } from "ai";

export interface Session {
  timestamp: number;
  title: string;
  createdAt: string;
  modifiedAt: string;
  history: UIMessage[];
}

type StoredSession = Omit<Session, "timestamp">;

const SESSIONS_DIR = path.join(process.cwd(), ".codify", "sessions");

const isMissingFileError = (error: unknown): boolean =>
  (error as NodeJS.ErrnoException)?.code === "ENOENT";

const readSession = async (timestamp: number): Promise<Session | null> => {
  const filePath = path.join(SESSIONS_DIR, `${timestamp}.json`);

  try {
    const raw = await fs.readFile(filePath, "utf-8");
    const data = JSON.parse(raw) as StoredSession;
    return { timestamp, ...data };
  } catch (error) {
    if (isMissingFileError(error)) {
      return null;
    }
    throw error;
  }
};

export const listSessions = async (limit?: number): Promise<Session[]> => {
  let entries: string[];

  try {
    entries = await fs.readdir(SESSIONS_DIR);
  } catch (error) {
    if (isMissingFileError(error)) {
      return [];
    }
    throw error;
  }

  const timestamps = entries
    .filter((name) => name.endsWith(".json"))
    .map((name) => Number.parseInt(path.basename(name, ".json"), 10))
    .filter((timestamp) => Number.isFinite(timestamp));

  const settled = await Promise.all(timestamps.map(readSession));

  const sessions = settled.filter(
    (session): session is Session => session !== null
  );

  sessions.sort((a, b) => {
    const modifiedDiff = b.modifiedAt.localeCompare(a.modifiedAt);
    if (modifiedDiff !== 0) {
      return modifiedDiff;
    }
    return b.createdAt.localeCompare(a.createdAt);
  });

  return limit === undefined ? sessions : sessions.slice(0, limit);
};

export const getSession = (timestamp: number): Promise<Session | null> =>
  readSession(timestamp);

export const saveSessionHistory = async (
  timestamp: number,
  history: UIMessage[]
): Promise<void> => {
  const filePath = path.join(SESSIONS_DIR, `${timestamp}.json`);
  const raw = await fs.readFile(filePath, "utf-8");
  const existing = JSON.parse(raw) as StoredSession;

  const updated: StoredSession = {
    ...existing,
    history,
    modifiedAt: new Date().toISOString(),
  };

  await fs.writeFile(filePath, JSON.stringify(updated, null, 2), "utf-8");
};

export const createSession = async (prompt: string): Promise<Session> => {
  const timestamp = Date.now();
  const now = new Date().toISOString();

  const session: Session = {
    createdAt: now,
    history: [
      {
        id: crypto.randomUUID(),
        parts: [{ text: prompt, type: "text" }],
        role: "user",
      },
    ],
    modifiedAt: now,
    timestamp,
    title: "Untitled",
  };

  await fs.mkdir(SESSIONS_DIR, { recursive: true });

  const { timestamp: _omitted, ...stored } = session;
  const filePath = path.join(SESSIONS_DIR, `${timestamp}.json`);
  await fs.writeFile(filePath, JSON.stringify(stored, null, 2), "utf-8");

  return session;
};

